export const recipeDuplicateCandidates = pgTable("recipe_duplicate_candidates", {
  id: integer("id").generatedByDefaultAsIdentity().primaryKey().notNull(),
  recipe_id: integer("recipe_id").notNull().references((): AnyPgColumn => recipes.id, { onDelete: "cascade" }),
  candidate_recipe_id: integer("candidate_recipe_id").notNull().references((): AnyPgColumn => recipes.id, { onDelete: "cascade" }),
  similarity: doublePrecision("similarity").notNull(),
  reasons_json: jsonb("reasons_json").notNull().default(sql.raw("'[]'::jsonb")),
  status: text("status").notNull().default("pending"),
  reviewed_by: integer("reviewed_by").references((): AnyPgColumn => users.id, { onDelete: "set null" }),
  reviewed_at: timestamp("reviewed_at", { withTimezone: true, mode: "string" }),
  created_at: timestamp("created_at", { withTimezone: true, mode: "string" }).notNull().defaultNow(),
}, (table) => [
  unique("recipe_duplicate_candidates_recipe_id_candidate_recipe_id_key").on(table.recipe_id, table.candidate_recipe_id),
  check("recipe_duplicate_candidates_check_1", sql.raw("similarity >= 0 AND similarity <= 1")),
  check("recipe_duplicate_candidates_check_2", sql.raw("status IN ('pending', 'merged', 'distinct', 'dismissed')")),
  check("recipe_duplicate_candidates_check_3", sql.raw("recipe_id < candidate_recipe_id")),
]);

