export const recipes = pgTable("recipes", {
  id: integer("id").generatedByDefaultAsIdentity().primaryKey().notNull(),
  title: text("title").notNull(),
  description: text("description"),
  image_url: text("image_url"),
  cook_time: integer("cook_time"),
  difficulty: text("difficulty"),
  calories: integer("calories"),
  protein: doublePrecision("protein"),
  carbs: doublePrecision("carbs"),
  fat: doublePrecision("fat"),
  nutrition_json: jsonb("nutrition_json"),
  category: text("category"),
  tags: jsonb("tags"),
  steps_json: jsonb("steps_json"),
  ingredients_json: jsonb("ingredients_json"),
  author_user_id: integer("author_user_id").references((): AnyPgColumn => users.id, { onDelete: "set null" }),
  source: text("source").default("official"),
  status: text("status").default("approved"),
  reviewed_by: integer("reviewed_by").references((): AnyPgColumn => users.id, { onDelete: "set null" }),
  reviewed_at: timestamp("reviewed_at", { withTimezone: true, mode: "string" }),
  reject_reason: text("reject_reason"),
  external_id: text("external_id"),
  source_url: text("source_url"),
  data_license: text("data_license"),
  source_revision: text("source_revision"),
  source_attribution: text("source_attribution"),
  updated_at: timestamp("updated_at", { withTimezone: true, mode: "string" }).defaultNow(),
  deleted_at: timestamp("deleted_at", { withTimezone: true, mode: "string" }),
  deleted_by: integer("deleted_by"),
  created_at: timestamp("created_at", { withTimezone: true, mode: "string" }).defaultNow(),
  quality_status: text("quality_status").notNull().default("trusted"),
  nutrition_basis: text("nutrition_basis").notNull().default("source"),
  quality_issues_json: jsonb("quality_issues_json").notNull().default(sql.raw("'[]'::jsonb")),
  quality_reviewed_by: integer("quality_reviewed_by"),
  quality_reviewed_at: timestamp("quality_reviewed_at", { withTimezone: true, mode: "string" }),
  quality_review_reason: text("quality_review_reason"),
  canonical_key: text("canonical_key"),
  source_content_hash: text("source_content_hash"),
  import_batch_id: text("import_batch_id"),
  serving_size: integer("serving_size"),
  prep_time: integer("prep_time"),
  cuisine: text("cuisine"),
  meal_types_json: jsonb("meal_types_json").notNull().default(sql.raw("'[]'::jsonb")),
  required_kitchenware_json: jsonb("required_kitchenware_json").notNull().default(sql.raw("'[]'::jsonb")),
  optional_kitchenware_json: jsonb("optional_kitchenware_json").notNull().default(sql.raw("'[]'::jsonb")),
  duplicate_of_recipe_id: integer("duplicate_of_recipe_id"),
  withdrawn_at: timestamp("withdrawn_at", { withTimezone: true, mode: "string" }),
  automatic_inventory_write_allowed: boolean("automatic_inventory_write_allowed").notNull().default(true),
  base_data_payload: jsonb("base_data_payload"),
  execution_json: jsonb("execution_json"),
}, (table) => [
  uniqueIndex("idx_recipes_source_external_id").on(table.source, table.external_id).where(sql.raw("external_id IS NOT NULL")),
  index("idx_recipes_author_created_at").on(table.author_user_id, table.created_at),
  index("idx_recipes_status_source").on(table.status, table.source, table.deleted_at),
  index("idx_recipes_deleted_at").on(table.deleted_at),
  index("idx_recipes_canonical_quality").on(table.canonical_key, table.quality_status).where(sql.raw("deleted_at IS NULL")),
  index("idx_recipes_quality_review").on(table.quality_status, table.source, table.id.desc()).where(sql.raw("deleted_at IS NULL")),
  index("idx_recipes_public_quality").on(table.status, table.quality_status, table.id.desc()).where(sql.raw("deleted_at IS NULL")),
]);

